package in.carenest.clinic.api;

import in.carenest.clinic.security.SecurityConfig.TenantPrincipal;
import com.lowagie.text.Document;
import com.lowagie.text.FontFactory;
import com.lowagie.text.Paragraph;
import com.lowagie.text.pdf.PdfWriter;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.io.ByteArrayOutputStream;
import java.time.*;
import java.util.*;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController @RequestMapping("/api")
public class OperationsApi {
 private final JdbcTemplate db; public OperationsApi(JdbcTemplate db){this.db=db;}
 record RoomInput(@NotBlank String name,@NotBlank String roomType,Boolean active){}
 @GetMapping("/rooms") List<Map<String,Object>> rooms(@AuthenticationPrincipal TenantPrincipal p){tenant(p);return db.queryForList("select id,name,room_type,active from rooms where clinic_id=? and branch_id=? order by room_type,name",p.clinicId(),p.branchId());}
 @PostMapping("/rooms") @ResponseStatus(HttpStatus.CREATED) Map<String,Object> addRoom(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody RoomInput x){owner(p);UUID id=UUID.randomUUID();db.update("insert into rooms(id,clinic_id,branch_id,name,room_type,active) values(?,?,?,?,?,?)",id,p.clinicId(),p.branchId(),x.name(),x.roomType(),x.active()==null||x.active());return Map.of("id",id);}
 @PutMapping("/rooms/{id}") Map<String,Object> updateRoom(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id,@Valid @RequestBody RoomInput x){owner(p);int n=db.update("update rooms set name=?,room_type=?,active=? where id=? and clinic_id=? and branch_id=?",x.name(),x.roomType(),x.active()==null||x.active(),id,p.clinicId(),p.branchId());if(n==0)throw error(HttpStatus.NOT_FOUND,"Room not found");return Map.of("id",id);}

 record ServiceInput(@NotBlank String name,@NotBlank String category,@NotBlank String roomType,@Min(15) int minutes,@DecimalMin("0.00") BigDecimal price,@DecimalMin("0.00") BigDecimal discountPercent,Boolean active){}
 @PostMapping("/services") @ResponseStatus(HttpStatus.CREATED) Map<String,Object> addService(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody ServiceInput x){owner(p);UUID id=UUID.randomUUID();db.update("insert into services(id,clinic_id,name,category,room_type,minutes,price,discount_percent,active) values(?,?,?,?,?,?,?,?,?)",id,p.clinicId(),x.name(),x.category(),x.roomType(),x.minutes(),x.price(),x.discountPercent(),x.active()==null||x.active());return Map.of("id",id);}
 record ProductInput(@NotBlank String name,String description,@DecimalMin("0.00") BigDecimal price,@Min(0) int stockQuantity){}
 @GetMapping("/products") List<Map<String,Object>> products(@AuthenticationPrincipal TenantPrincipal p){tenant(p);return db.queryForList("select id,name,description,price,stock_quantity,active from products where clinic_id=? order by name",p.clinicId());}
 @PostMapping("/products") @ResponseStatus(HttpStatus.CREATED) Map<String,Object> addProduct(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody ProductInput x){owner(p);UUID id=UUID.randomUUID();db.update("insert into products(id,clinic_id,name,description,price,stock_quantity) values(?,?,?,?,?,?)",id,p.clinicId(),x.name(),x.description(),x.price(),x.stockQuantity());return Map.of("id",id);}
 record PackageInput(@NotBlank String name,@NotNull UUID serviceId,@Min(1) int sessionCount,@DecimalMin("0.00") BigDecimal price){}
 @GetMapping("/packages") List<Map<String,Object>> packages(@AuthenticationPrincipal TenantPrincipal p){tenant(p);return db.queryForList("select p.id,p.name,p.session_count,p.price,p.active,s.name service from packages p left join services s on s.id=p.service_id where p.clinic_id=? order by p.name",p.clinicId());}
 @PostMapping("/packages") @ResponseStatus(HttpStatus.CREATED) Map<String,Object> addPackage(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody PackageInput x){owner(p);UUID id=UUID.randomUUID();int n=db.update("insert into packages(id,clinic_id,name,service_id,session_count,price) select ?,?,?,?,?,? where exists(select 1 from services where id=? and clinic_id=?)",id,p.clinicId(),x.name(),x.serviceId(),x.sessionCount(),x.price(),x.serviceId(),p.clinicId());if(n==0)throw error(HttpStatus.BAD_REQUEST,"Service does not belong to this clinic");return Map.of("id",id);}

 @GetMapping("/practitioners") List<Map<String,Object>> practitioners(@AuthenticationPrincipal TenantPrincipal p){tenant(p);return db.queryForList("""
 select pr.id,pr.full_name,pr.dob,pr.joined_on,pr.engagement,pr.years_experience,pr.rate,pr.salary,pr.phone,pr.active,u.username,
 coalesce(string_agg(distinct s.name,', '),'') services,coalesce(string_agg(distinct pa.day_of_week||':'||pa.starts_at||'-'||pa.ends_at,', '),'') availability
 from practitioners pr left join users u on u.id=pr.user_id left join practitioner_services ps on ps.practitioner_id=pr.id
 left join services s on s.id=ps.service_id left join practitioner_availability pa on pa.practitioner_id=pr.id
 where pr.clinic_id=? and pr.branch_id=? group by pr.id,u.username order by pr.full_name
 """,p.clinicId(),p.branchId());}
 record Availability(@Min(1)@Max(7) int dayOfWeek,@NotNull LocalTime startsAt,@NotNull LocalTime endsAt){}
 record PractitionerInput(@Email String username,@Size(min=12) String password,@NotBlank String displayName,String phone,LocalDate dob,LocalDate joinedOn,@NotBlank String engagement,@DecimalMin("0") BigDecimal yearsExperience,BigDecimal rate,BigDecimal salary,List<UUID> serviceIds,List<Availability> availability,String photoBase64,String photoContentType,String documentZipBase64,String documentZipName,Boolean createLogin){}
 @PostMapping("/practitioners/onboard") @Transactional @ResponseStatus(HttpStatus.CREATED) Map<String,Object> onboardPractitioner(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody PractitionerInput x){owner(p);UUID user=null;if(Boolean.TRUE.equals(x.createLogin())){if(x.username()==null||x.password()==null)throw error(HttpStatus.BAD_REQUEST,"Login email and temporary password are required");user=UUID.randomUUID();db.update("insert into users(id,clinic_id,branch_id,username,password_hash,display_name,role,phone,joined_on) values(?,?,?,?,crypt(?,gen_salt('bf')),?,'PRACTITIONER',?,?)",user,p.clinicId(),p.branchId(),x.username(),x.password(),x.displayName(),x.phone(),date(x.joinedOn()));}UUID id=UUID.randomUUID();db.update("insert into practitioners(id,clinic_id,user_id,branch_id,full_name,dob,joined_on,engagement,years_experience,rate,salary,phone,photo_data,photo_content_type,document_archive,document_archive_name) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,p.clinicId(),user,p.branchId(),x.displayName(),x.dob(),date(x.joinedOn()),x.engagement(),zero(x.yearsExperience()),x.rate(),x.salary(),x.phone(),decode(x.photoBase64()),x.photoContentType(),decode(x.documentZipBase64()),x.documentZipName());for(UUID service:orEmpty(x.serviceIds())){int n=db.update("insert into practitioner_services(practitioner_id,service_id) select ?,id from services where id=? and clinic_id=? on conflict do nothing",id,service,p.clinicId());if(n==0)throw error(HttpStatus.BAD_REQUEST,"Invalid practitioner service");}for(Availability a:orEmpty(x.availability())){if(!a.startsAt().isBefore(a.endsAt()))throw error(HttpStatus.BAD_REQUEST,"Availability start must be before end");db.update("insert into practitioner_availability(clinic_id,practitioner_id,day_of_week,starts_at,ends_at) values(?,?,?,?,?)",p.clinicId(),id,a.dayOfWeek(),a.startsAt(),a.endsAt());}Map<String,Object> out=new LinkedHashMap<>();out.put("practitionerId",id);out.put("userId",user);return out;}
 record ReceptionistInput(@Email String username,@Size(min=12) String password,@NotBlank String displayName,String phone,LocalDate joinedOn){}
 @PostMapping("/receptionists") @ResponseStatus(HttpStatus.CREATED) Map<String,Object> receptionist(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody ReceptionistInput x){owner(p);UUID id=UUID.randomUUID();db.update("insert into users(id,clinic_id,branch_id,username,password_hash,display_name,role,phone,joined_on) values(?,?,?,?,crypt(?,gen_salt('bf')),?,'RECEPTIONIST',?,?)",id,p.clinicId(),p.branchId(),x.username(),x.password(),x.displayName(),x.phone(),date(x.joinedOn()));return Map.of("userId",id);}
 @GetMapping("/practitioners/{id}/services") List<Map<String,Object>> practitionerServices(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id){tenant(p);return db.queryForList("select s.id,s.name,s.minutes,s.price,s.room_type from services s join practitioner_services ps on ps.service_id=s.id join practitioners pr on pr.id=ps.practitioner_id where ps.practitioner_id=? and pr.clinic_id=? and s.active order by s.name",id,p.clinicId());}

 @GetMapping("/slots") List<Map<String,Object>> slots(@AuthenticationPrincipal TenantPrincipal p,@RequestParam UUID practitionerId,@RequestParam UUID serviceId,@RequestParam LocalDate date){tenant(p);Integer practitioner=db.queryForObject("select count(*) from practitioners where id=? and clinic_id=? and branch_id=? and active",Integer.class,practitionerId,p.clinicId(),p.branchId());if(practitioner==0)throw error(HttpStatus.NOT_FOUND,"Practitioner not found");var branch=db.queryForMap("select opens_at,closes_at from branches where id=? and clinic_id=?",p.branchId(),p.clinicId());var svc=db.queryForMap("select minutes,room_type from services where id=? and clinic_id=? and active",serviceId,p.clinicId());LocalTime open=toLocalTime(branch.get("opens_at")),close=toLocalTime(branch.get("closes_at"));int minutes=((Number)svc.get("minutes")).intValue();Integer configured=db.queryForObject("select count(*) from practitioner_availability where practitioner_id=?",Integer.class,practitionerId);List<Map<String,Object>> out=new ArrayList<>();for(LocalTime t=open;!t.plusMinutes(minutes).isAfter(close);t=t.plusMinutes(minutes)){LocalDateTime start=LocalDateTime.of(date,t),end=start.plusMinutes(minutes);Integer matching=db.queryForObject("select count(*) from practitioner_availability where practitioner_id=? and day_of_week=? and starts_at<=? and ends_at>=?",Integer.class,practitionerId,date.getDayOfWeek().getValue(),t,t.plusMinutes(minutes));boolean scheduled=configured==0||matching>0;Integer busy=db.queryForObject("select count(*) from appointments where clinic_id=? and practitioner_id=? and status='BOOKED' and starts_at<? and ends_at>?",Integer.class,p.clinicId(),practitionerId,end,start);Integer room=db.queryForObject("select count(*) from rooms r where r.clinic_id=? and r.branch_id=? and r.room_type=? and r.active and not exists(select 1 from appointments a where a.room_id=r.id and a.status='BOOKED' and a.starts_at<? and a.ends_at>?)",Integer.class,p.clinicId(),p.branchId(),svc.get("room_type"),end,start);if(scheduled&&busy==0&&room>0)out.add(Map.of("startsAt",start,"label",t.toString(),"available",true,"scheduleSource",configured==0?"BRANCH_HOURS":"PRACTITIONER"));}return out;}
 @GetMapping("/availability/month") List<Map<String,Object>> monthAvailability(@AuthenticationPrincipal TenantPrincipal p,@RequestParam UUID practitionerId,@RequestParam UUID serviceId,@RequestParam YearMonth month){tenant(p);if(month.isBefore(YearMonth.now()))throw error(HttpStatus.BAD_REQUEST,"Past months cannot be booked");List<Map<String,Object>> out=new ArrayList<>();for(int day=1;day<=month.lengthOfMonth();day++){LocalDate date=month.atDay(day);if(date.isBefore(LocalDate.now()))continue;for(Map<String,Object> slot:slots(p,practitionerId,serviceId,date)){if(Boolean.TRUE.equals(slot.get("available"))){Map<String,Object> item=new LinkedHashMap<>(slot);item.put("date",date);item.put("weekday",date.getDayOfWeek().toString());out.add(item);}}}return out;}
 record SeriesBooking(@NotNull UUID customerId,@NotNull UUID practitionerId,@NotNull UUID serviceId,@NotEmpty List<LocalDateTime> startsAt){}
 @PostMapping("/appointments/series") @Transactional @ResponseStatus(HttpStatus.CREATED) Map<String,Object> bookSeries(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody SeriesBooking x){tenant(p);UUID series=UUID.randomUUID();List<UUID> ids=new ArrayList<>();for(LocalDateTime start:x.startsAt())ids.add(book(p,x.customerId(),x.practitionerId(),x.serviceId(),start,series));return Map.of("seriesId",series,"appointmentIds",ids,"count",ids.size());}
 private UUID book(TenantPrincipal p,UUID customer,UUID practitioner,UUID serviceId,LocalDateTime start,UUID series){var service=db.queryForMap("select room_type,minutes,price*(1-discount_percent/100) price from services where id=? and clinic_id=? and active",serviceId,p.clinicId());int mins=((Number)service.get("minutes")).intValue();LocalDateTime end=start.plusMinutes(mins);Integer enabled=db.queryForObject("select count(*) from practitioner_services where practitioner_id=? and service_id=?",Integer.class,practitioner,serviceId);if(enabled==0)throw error(HttpStatus.CONFLICT,"Practitioner does not provide this service");Integer configured=db.queryForObject("select count(*) from practitioner_availability where practitioner_id=?",Integer.class,practitioner);Integer scheduled=db.queryForObject("select count(*) from practitioner_availability where practitioner_id=? and day_of_week=? and starts_at<=? and ends_at>=?",Integer.class,practitioner,start.getDayOfWeek().getValue(),start.toLocalTime(),end.toLocalTime());if(configured>0&&scheduled==0)throw error(HttpStatus.CONFLICT,"Practitioner is outside configured availability");Integer busy=db.queryForObject("select count(*) from appointments where clinic_id=? and practitioner_id=? and status='BOOKED' and starts_at<? and ends_at>?",Integer.class,p.clinicId(),practitioner,end,start);if(busy>0)throw error(HttpStatus.CONFLICT,"Practitioner is not available");var rooms=db.queryForList("select r.id from rooms r where r.clinic_id=? and r.branch_id=? and r.room_type=? and r.active and not exists(select 1 from appointments a where a.room_id=r.id and a.status='BOOKED' and a.starts_at<? and a.ends_at>?) order by r.name limit 1",UUID.class,p.clinicId(),p.branchId(),service.get("room_type"),end,start);if(rooms.isEmpty())throw error(HttpStatus.CONFLICT,"No suitable room is available");UUID id=UUID.randomUUID();db.update("insert into appointments(id,clinic_id,branch_id,customer_id,practitioner_id,service_id,room_id,starts_at,ends_at,price,series_id,booked_by) values(?,?,?,?,?,?,?,?,?,?,?,?)",id,p.clinicId(),p.branchId(),customer,practitioner,serviceId,rooms.getFirst(),start,end,service.get("price"),series,p.userId());db.update("insert into booking_events(clinic_id,appointment_id,event_type,actor_user_id,new_values) values(?,?,'BOOKED',?,jsonb_build_object('startsAt',?::text))",p.clinicId(),id,p.userId(),start.toString());return id;}
 @GetMapping("/appointments") List<Map<String,Object>> appointments(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(required=false) LocalDate date,@RequestParam(required=false) UUID customerId,@RequestParam(required=false) UUID practitionerId){tenant(p);LocalDate d=date==null?LocalDate.now():date;return db.queryForList("select a.id,a.series_id,a.customer_id,a.practitioner_id,a.service_id,a.starts_at,a.ends_at,a.status,a.price,a.attendance_comment,c.full_name customer,pr.full_name practitioner,s.name service,r.name room from appointments a join customers c on c.id=a.customer_id join practitioners pr on pr.id=a.practitioner_id join services s on s.id=a.service_id join rooms r on r.id=a.room_id where a.clinic_id=? and a.branch_id=? and a.starts_at>=? and a.starts_at<? and (?::uuid is null or a.customer_id=?) and (?::uuid is null or a.practitioner_id=?) order by a.starts_at",p.clinicId(),p.branchId(),d.atStartOfDay(),d.plusDays(1).atStartOfDay(),customerId,customerId,practitionerId,practitionerId);}
 record AppointmentChange(@NotNull UUID serviceId,@NotNull LocalDateTime startsAt){}
 @PutMapping("/appointments/{id}") @Transactional Map<String,Object> changeAppointment(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id,@Valid @RequestBody AppointmentChange x){tenant(p);var current=db.queryForMap("select customer_id,practitioner_id,service_id,starts_at,status from appointments where id=? and clinic_id=? and branch_id=? for update",id,p.clinicId(),p.branchId());if(!"BOOKED".equals(current.get("status")))throw error(HttpStatus.CONFLICT,"Only booked appointments can be modified");UUID practitioner=(UUID)current.get("practitioner_id");var service=db.queryForMap("select room_type,minutes,price*(1-discount_percent/100) price from services where id=? and clinic_id=? and active",x.serviceId(),p.clinicId());int enabled=db.queryForObject("select count(*) from practitioner_services where practitioner_id=? and service_id=?",Integer.class,practitioner,x.serviceId());if(enabled==0)throw error(HttpStatus.CONFLICT,"Practitioner does not provide this service");LocalDateTime end=x.startsAt().plusMinutes((Integer)service.get("minutes"));int busy=db.queryForObject("select count(*) from appointments where clinic_id=? and practitioner_id=? and id<>? and status='BOOKED' and starts_at<? and ends_at>?",Integer.class,p.clinicId(),practitioner,id,end,x.startsAt());if(busy>0)throw error(HttpStatus.CONFLICT,"Practitioner is not available");var rooms=db.queryForList("select r.id from rooms r where r.clinic_id=? and r.branch_id=? and r.room_type=? and r.active and not exists(select 1 from appointments a where a.room_id=r.id and a.id<>? and a.status='BOOKED' and a.starts_at<? and a.ends_at>?) order by r.name limit 1",UUID.class,p.clinicId(),p.branchId(),service.get("room_type"),id,end,x.startsAt());if(rooms.isEmpty())throw error(HttpStatus.CONFLICT,"No suitable room is available");db.update("update appointments set service_id=?,room_id=?,starts_at=?,ends_at=?,price=?,version=version+1 where id=?",x.serviceId(),rooms.getFirst(),x.startsAt(),end,service.get("price"),id);db.update("insert into booking_events(clinic_id,appointment_id,event_type,actor_user_id,old_values,new_values) values(?,?,'MODIFIED',?,jsonb_build_object('serviceId',?::text,'startsAt',?::text),jsonb_build_object('serviceId',?::text,'startsAt',?::text))",p.clinicId(),id,p.userId(),current.get("service_id").toString(),current.get("starts_at").toString(),x.serviceId().toString(),x.startsAt().toString());return Map.of("id",id,"status","MODIFIED");}
 record AttendanceInput(@NotBlank String status,String comment){}
 @PutMapping("/appointments/{id}/attendance") @Transactional Map<String,Object> attendance(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id,@Valid @RequestBody AttendanceInput x){tenant(p);if(!List.of("DONE","NO_SHOW").contains(x.status()))throw error(HttpStatus.BAD_REQUEST,"Status must be DONE or NO_SHOW");int updated=db.update("update appointments set status=?,attendance_comment=?,version=version+1 where id=? and clinic_id=? and branch_id=? and status='BOOKED'",x.status(),x.comment(),id,p.clinicId(),p.branchId());if(updated==0)throw error(HttpStatus.CONFLICT,"Appointment is not available for attendance");return Map.of("id",id,"status",x.status());}

 @GetMapping("/payments") List<Map<String,Object>> payments(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(required=false) UUID customerId){tenant(p);return db.queryForList("select p.id,p.amount,p.adjustment,p.status,p.method,p.receipt_number,p.receipt_url,p.confirmed_at,c.full_name customer from payments p join customers c on c.id=p.customer_id where p.clinic_id=? and p.branch_id=? and (?::uuid is null or p.customer_id=?) order by p.created_at desc limit 100",p.clinicId(),p.branchId(),customerId,customerId);}
 @GetMapping("/payments/due/{customerId}") Map<String,Object> due(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID customerId){tenant(p);BigDecimal sessions=db.queryForObject("select coalesce(sum(price),0) from appointments where clinic_id=? and customer_id=? and status in ('BOOKED','DONE','NO_SHOW')",BigDecimal.class,p.clinicId(),customerId);BigDecimal cancellation=db.queryForObject("select coalesce(sum(be.charge),0) from booking_events be join appointments a on a.id=be.appointment_id where be.clinic_id=? and a.customer_id=?",BigDecimal.class,p.clinicId(),customerId);BigDecimal paid=db.queryForObject("select coalesce(sum(amount),0) from payments where clinic_id=? and customer_id=? and status='CONFIRMED'",BigDecimal.class,p.clinicId(),customerId);return Map.of("sessionCharges",sessions,"cancellationCharges",cancellation,"paid",paid,"due",sessions.add(cancellation).subtract(paid));}
 @GetMapping(value="/payments/{id}/receipt",produces=MediaType.TEXT_HTML_VALUE) ResponseEntity<String> receipt(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id){tenant(p);var x=db.queryForMap("select p.receipt_number,p.amount,p.method,p.confirmed_at,c.full_name customer,cl.name clinic,b.name branch from payments p join customers c on c.id=p.customer_id join clinics cl on cl.id=p.clinic_id join branches b on b.id=p.branch_id where p.id=? and p.clinic_id=?",id,p.clinicId());String html="<html><head><title>Receipt "+x.get("receipt_number")+"</title><style>body{font:16px sans-serif;max-width:600px;margin:50px auto}h1{color:#285046}.total{font-size:24px}</style></head><body><h1>"+x.get("clinic")+"</h1><p>"+x.get("branch")+"</p><hr><h2>Payment receipt</h2><p>Receipt: "+x.get("receipt_number")+"</p><p>Customer: "+x.get("customer")+"</p><p>Method: "+x.get("method")+"</p><p class=total>Paid: ₹"+x.get("amount")+"</p><p>Confirmed: "+x.get("confirmed_at")+"</p></body></html>";return ResponseEntity.ok().contentType(MediaType.TEXT_HTML).body(html);}
 @GetMapping(value="/public/receipts/{id}",produces=MediaType.TEXT_HTML_VALUE) ResponseEntity<String> publicReceipt(@PathVariable UUID id){var x=db.queryForMap("select p.receipt_number,p.amount,p.method,p.confirmed_at,c.full_name customer,cl.name clinic,b.name branch from payments p join customers c on c.id=p.customer_id join clinics cl on cl.id=p.clinic_id join branches b on b.id=p.branch_id where p.id=? and p.status='CONFIRMED'",id);String html="<html><head><meta name=viewport content='width=device-width,initial-scale=1'><title>Receipt "+x.get("receipt_number")+"</title><style>body{font:16px sans-serif;max-width:600px;margin:30px auto;padding:20px}h1{color:#285046}.total{font-size:24px}</style></head><body><h1>"+x.get("clinic")+"</h1><p>"+x.get("branch")+"</p><hr><h2>Payment receipt</h2><p>Receipt: "+x.get("receipt_number")+"</p><p>Customer: "+x.get("customer")+"</p><p>Method: "+x.get("method")+"</p><p class=total>Paid: ₹"+x.get("amount")+"</p><p>Confirmed: "+x.get("confirmed_at")+"</p></body></html>";return ResponseEntity.ok().contentType(MediaType.TEXT_HTML).body(html);}
 @GetMapping(value="/public/receipts/{id}/pdf",produces=MediaType.APPLICATION_PDF_VALUE) ResponseEntity<byte[]> receiptPdf(@PathVariable UUID id){var x=db.queryForMap("select p.receipt_number,p.amount,p.adjustment,p.notes,p.method,p.confirmed_at,c.full_name customer,cl.name clinic,b.name branch from payments p join customers c on c.id=p.customer_id join clinics cl on cl.id=p.clinic_id join branches b on b.id=p.branch_id where p.id=? and p.status='CONFIRMED'",id);ByteArrayOutputStream bytes=new ByteArrayOutputStream();Document doc=new Document();PdfWriter.getInstance(doc,bytes);doc.open();doc.add(new Paragraph(String.valueOf(x.get("clinic")),FontFactory.getFont(FontFactory.HELVETICA_BOLD,20)));doc.add(new Paragraph(String.valueOf(x.get("branch"))));doc.add(new Paragraph(" "));doc.add(new Paragraph("PAYMENT RECEIPT",FontFactory.getFont(FontFactory.HELVETICA_BOLD,16)));doc.add(new Paragraph("Receipt: "+x.get("receipt_number")));doc.add(new Paragraph("Customer: "+x.get("customer")));doc.add(new Paragraph("Method: "+x.get("method")));doc.add(new Paragraph("Paid: INR "+x.get("amount"),FontFactory.getFont(FontFactory.HELVETICA_BOLD,15)));doc.add(new Paragraph("Adjustment: INR "+x.get("adjustment")));if(x.get("notes")!=null)doc.add(new Paragraph("Note: "+x.get("notes")));doc.add(new Paragraph("Confirmed: "+x.get("confirmed_at")));doc.close();return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+x.get("receipt_number")+".pdf\"").body(bytes.toByteArray());}

 @GetMapping("/settings") Map<String,Object> settings(@AuthenticationPrincipal TenantPrincipal p){owner(p);return db.queryForMap("select c.name,c.logo_url,c.theme,c.owner_phone,c.whatsapp_phone,c.email,c.default_slot_minutes,c.free_customer_cancellations,c.practitioner_cancel_credit,c.cancellation_notice_hours,b.name branch_name,b.address,b.opens_at,b.closes_at from clinics c join branches b on b.id=? where c.id=?",p.branchId(),p.clinicId());}
 record SettingsInput(@NotBlank String theme,@Min(15)@Max(180) int defaultSlotMinutes,@Min(0) int freeCustomerCancellations,@Min(0) int practitionerCancelCredit,@Min(0) int cancellationNoticeHours,@NotNull LocalTime opensAt,@NotNull LocalTime closesAt,String whatsappPhone,String email,String logoUrl,String paymentOtp){}
 @PutMapping("/settings") @Transactional Map<String,Object> updateSettings(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody SettingsInput x){owner(p);if(!Set.of("terracotta","sage","sunset","rose","sand","plum","ocean","marigold","lavender").contains(x.theme()))throw error(HttpStatus.BAD_REQUEST,"Unsupported theme");if(!x.opensAt().isBefore(x.closesAt()))throw error(HttpStatus.BAD_REQUEST,"Opening time must be before closing time");db.update("update clinics set theme=?,default_slot_minutes=?,free_customer_cancellations=?,practitioner_cancel_credit=?,cancellation_notice_hours=?,whatsapp_phone=?,email=?,logo_url=? where id=?",x.theme(),x.defaultSlotMinutes(),x.freeCustomerCancellations(),x.practitionerCancelCredit(),x.cancellationNoticeHours(),x.whatsappPhone(),x.email(),x.logoUrl(),p.clinicId());if(x.paymentOtp()!=null&&!x.paymentOtp().isBlank()){if(!x.paymentOtp().matches("\\d{6}"))throw error(HttpStatus.BAD_REQUEST,"Payment OTP must contain 6 digits");db.update("update clinics set payment_otp_hash=crypt(?,gen_salt('bf')) where id=?",x.paymentOtp(),p.clinicId());}db.update("update branches set opens_at=?,closes_at=? where id=? and clinic_id=?",x.opensAt(),x.closesAt(),p.branchId(),p.clinicId());return Map.of("status","UPDATED");}
 @GetMapping("/whatsapp/service-menu") Map<String,Object> whatsappMenu(@AuthenticationPrincipal TenantPrincipal p){tenant(p);var clinic=db.queryForMap("select name,whatsapp_phone from clinics where id=?",p.clinicId());var services=db.queryForList("select name,minutes,price,discount_percent from services where clinic_id=? and active order by name",p.clinicId());return Map.of("clinic",clinic,"services",services,"format","NUMBERED_LIST");}
 private void tenant(TenantPrincipal p){if(p==null||p.clinicId()==null)throw error(HttpStatus.FORBIDDEN,"Clinic context required");}
 private void owner(TenantPrincipal p){tenant(p);if(!"OWNER".equals(p.role()))throw error(HttpStatus.FORBIDDEN,"Clinic owner required");}
 private LocalDate date(LocalDate d){return d==null?LocalDate.now():d;} private LocalTime toLocalTime(Object value){if(value instanceof LocalTime time)return time;if(value instanceof java.sql.Time time)return time.toLocalTime();return LocalTime.parse(String.valueOf(value));} private BigDecimal zero(BigDecimal n){return n==null?BigDecimal.ZERO:n;} private byte[] decode(String v){return v==null||v.isBlank()?null:Base64.getDecoder().decode(v);} private <T> List<T> orEmpty(List<T> v){return v==null?List.of():v;} private ResponseStatusException error(HttpStatus s,String m){return new ResponseStatusException(s,m);}
}
